const item = $input.first();
const bin  = item.binary || {};

const resumeBin = bin.resume || bin.data || bin.file;
if (!resumeBin) throw new Error('No resume binary found. Ensure the file field is named "resume" and Binary Data is ON in the Webhook node.');

const body = item.json?.body ?? item.json ?? {};

const parseJSON = (val, fallback) => {
  if (!val) return fallback;
  try { return JSON.parse(val); } catch(_) { return fallback; }
};

return [{
  json: {
    resumeBase64: resumeBin.data,
    mimeType:     resumeBin.mimeType || 'application/pdf',
    fileName:     resumeBin.fileName || 'resume.pdf',
    locations:    parseJSON(body.locations, []),
    roles:        parseJSON(body.roles, []),
    salaryMin:    parseInt(body.salaryMin ?? '0',   10),
    salaryMax:    parseInt(body.salaryMax ?? '200', 10)
  }
}];

const pdfResult = $input.first().json;
const prefs     = $('Extract Binary').first().json;

if (!pdfResult.text) throw new Error('PDF text extraction returned empty. Firebase response: ' + JSON.stringify(pdfResult));

return [{
  json: {
    resumeText: pdfResult.text,
    locations:  prefs.locations,
    roles:      prefs.roles,
    salaryMin:  prefs.salaryMin,
    salaryMax:  prefs.salaryMax
  }
}];

const openaiResponse = $input.first().json;
const prefs = $('Build OpenAI Prompt').first().json;

let profile;
try {
  const content = openaiResponse.choices[0].message.content;
  profile = typeof content === 'string' ? JSON.parse(content) : content;
} catch(e) {
  throw new Error('Failed to parse OpenAI response: ' + e.message);
}

profile.avoidKeywords     = profile.avoidKeywords     || [];
profile.seniorityKeywords = profile.seniorityKeywords || [];
profile.industries        = profile.industries        || [];
profile.locations         = prefs.locations;
profile.roles             = prefs.roles;
profile.salaryMin         = prefs.salaryMin;
profile.salaryMax         = prefs.salaryMax;

return [{ json: profile }];
